L["event.alterac_dawn_trout.name"] = "Truchas al alba"
L["event.alterac_dawn_trout.note"] = "Lagos fríos entre las cumbres. La apuesta es trucha antes del desayuno, y la escarcha en el sedal va de regalo."
L["event.azshara_lobster.name"] = "Langosta a la luz del farol"
L["event.azshara_lobster.note"] = "Una costa rota de piedra caída y grandeza marchita. Las langostas no se apartan de las rocas, y las colas amarillas guardan las distancias."
L["event.barrens_oddities.name"] = "Bichos raros al ocaso"
L["event.barrens_oddities.note"] = "Las charcas de las llanuras secas dan algún pez extraño. Revísalos al ponerse el sol, y piénsatelo dos veces antes de cocinar ninguno."
L["event.burning_steppes_salmon.name"] = "Salmón bajo la ceniza"
L["event.burning_steppes_salmon.note"] = "Colinas negras, ceniza en el agua y salmones debajo. Trae un sombrero de ala ancha."
L["event.darkshore_moonlight.name"] = "Meros bajo la luna"
L["event.darkshore_moonlight.note"] = "Una larga costa gris bajo árboles viejos y oscuros. La apuesta es mero con la luna ya alta, y allí las noches son largas."
L["event.deadwind_pass_night.name"] = "Paso frío, noche larga"
L["event.deadwind_pass_night.note"] = "Un paso frío donde nada crece, y una vieja torre vigilando el camino. A los salmones les trae sin cuidado."
L["event.duskwood_witching.name"] = "La hora de las brujas"
L["event.duskwood_witching.note"] = "Ríos negros y lentos entre bosques donde nunca acaba de hacerse de día. Pasada la medianoche pican los peces, y todo lo demás también."
L["event.dustwallow_marsh_night.name"] = "Noche cerrada en la ciénaga"
L["event.dustwallow_marsh_night.note"] = "Una costa cálida y húmeda que zumba toda la noche. Truchas en los arroyos, colas amarillas frente a la orilla y siempre algo picándote en el cuello."
L["event.eastern_plaguelands_night.name"] = "Medianoche en el este muerto"
L["event.eastern_plaguelands_night.note"] = "Nadie pesca en el este muerto de noche si puede evitarlo. Los salmones ya cuentan con ello."
L["event.eastern_plaguelands_redgill.name"] = "Lagos lúgubres del este"
L["event.eastern_plaguelands_redgill.note"] = "Lúgubres por fuera y generosos por dentro, como casi todos los buenos lagos y algunos pescadores viejos."
L["event.felwood_moonglade.name"] = "Bosque corrupto, lago claro"
L["event.felwood_moonglade.note"] = "Arroyos enfermizos bajo los árboles corruptos, y más allá un lago claro y tranquilo. A las agallarrojas no parece importarles la diferencia."
L["event.feralas_redgill.name"] = "Agallarrojas bajo la lluvia"
L["event.feralas_redgill.note"] = "Agallarrojas río arriba, colas amarillas frente a la costa y lluvia sobre ambas. El bosque nunca acaba de secarse."
L["event.hinterlands_coast.name"] = "Colinas hasta el mar"
L["event.hinterlands_coast.note"] = "Colinas salvajes, grifos en el cielo y un mar tranquilo al fondo de todo. Lo que nada allá abajo compensa la bajada."
L["event.hinterlands_redgill.name"] = "Ríos fríos, noches largas"
L["event.hinterlands_redgill.note"] = "Ríos claros y fríos entre las colinas salvajes. Las agallarrojas trasnochan, así que trae otra manta."
L["event.loch_modan_frenzy.name"] = "Aguas de frenesí"
L["event.loch_modan_frenzy.note"] = "Un lago ancho y frío en tierra de enanos, donde los peces pelean por encima de su tamaño. De vez en cuando sale con ellos algo más fino."
L["event.silithus_coast.name"] = "Arena hasta la orilla"
L["event.silithus_coast.note"] = "Arena hasta el agua, y algo zumbando en las dunas de atrás. Pasado el oleaje, todo es pescado de mar honrado."
L["event.silithus_salmon.name"] = "Salmones en la arena"
L["event.silithus_salmon.note"] = "Un salmón de escama blanca tan al sur sorprende a todos, empezando por el salmón. Aprovecha mientras dure la luz."
L["event.stranglethorn_coast.name"] = "Orilla de la selva"
L["event.stranglethorn_coast.note"] = "Agua templada, playas largas y un bacalao bajo cada roca. No pierdas de vista la linde de la selva."
L["event.tanaris_yellowtail.name"] = "Mediodía en la costa árida"
L["event.tanaris_yellowtail.note"] = "Arena hasta la marea y ni una pizca de sombra. A las colas amarillas no les molesta el calor; al pescador, quizá sí."
L["event.tirisfal_silverpine_dusk.name"] = "Aguas grises al anochecer"
L["event.tirisfal_silverpine_dusk.note"] = "Agua fría bajo los bosques grises del norte, tranquila como un camposanto. Aquí nadie tiene prisa, y los peces menos que nadie."
L["event.ungoro_redgill.name"] = "Anochecer en el cráter"
L["event.ungoro_redgill.note"] = "Charcas humeantes al fondo del cráter, llenas de agallarrojas. Algo más grande vigila siempre desde los helechos."
L["event.western_plaguelands_lake.name"] = "Una tarde en la plaga"
L["event.western_plaguelands_lake.note"] = "Tierras muertas, un cielo enfermo y un lago lleno de agallarrojas sanas. Nadie les ha hablado de la peste."
L["event.winterspring_daylight.name"] = "Días cortos en la nieve"
L["event.winterspring_daylight.note"] = "Allá en la nieve los días son cortos y los lagos, fríos. Gasta la luz en el agua y la oscuridad junto al fuego."
L["event.winterspring_salmon.name"] = "Salmón entre nieves"
L["event.winterspring_salmon.note"] = "Agua fría, salmones blancos y tardes que oscurecen pronto. Cuidado con el hielo de vuelta a casa."
