L["huntgood.hunts.binding.fiveseal.description"] = "Cuero negro con sellos de lacre estampados, uno por cada serie de cazas que existe. Este no lo falsifica nadie."
L["huntgood.hunts.binding.fiveseal.name"] = "Sello de cinco series"
L["huntgood.hunts.binding.pathfinder.description"] = "Suave piel de becerro con una rosa de los vientos estampada. Para pescadores que llevaron una serie de cazas entera hasta el final."
L["huntgood.hunts.binding.pathfinder.name"] = "Becerro del explorador"
L["huntgood.hunts.binding.wagersilk.description"] = "Brocado de seda morada tejido con monedas y peces, cruzado por una banda roja. Para pescadores que no paran de ganar las apuestas de la casa."
L["huntgood.hunts.binding.wagersilk.name"] = "Brocado del ganador"
L["huntgood.hunts.soundset.nightwatch.description"] = "Una campana grave para la guardia nocturna, un farol que zumba y un búho que ha visto cada pieza que has sacado."
L["huntgood.hunts.soundset.nightwatch.name"] = "Guardia nocturna"
L["huntgood.hunts.toaststyle.nightfin.description"] = "Más allá del cabo, donde acaba la luz, los peces de la noche nadan bajo la luna llena. Quédate quieto el tiempo suficiente y uno la cruza de un salto."
L["huntgood.hunts.toaststyle.nightfin.name"] = "Aletas bajo la luna"
L["huntgood.hunts.toaststyle.study.description"] = "Un cuaderno abierto sobre un escritorio, la lámpara aún encendida y el tintero destapado, sus mejores moscas colgadas en el aire tibio sobre la página. Nadie lo ha pillado nunca en ello. Tampoco nadie ha visto nunca el escritorio vacío."
L["huntgood.hunts.toaststyle.study.name"] = "El estudio de Nat"
L["huntgood.hunts.toaststyle.trench.description"] = "Por debajo de donde se rinde la luz del sol, y por debajo de donde se rinden los faroles de los rapes. Aquí abajo vive algo muy grande, y se ha fijado en el sedal."
L["huntgood.hunts.toaststyle.trench.name"] = "La fosa profunda"
L["huntgood.hunts.trackerframe.bounty.description"] = "Clavado en la caseta del muelle, con las esquinas rizadas. El pez tiene precio, y el precio no deja de subir."
L["huntgood.hunts.trackerframe.bounty.name"] = "Cartel de recompensa"
L["huntgood.hunts.trackerframe.inkwash.description"] = "Una hoja escrita con tinta azul, la aguada algo corrida, como una página a la que le saltó la espuma."
L["huntgood.hunts.trackerframe.inkwash.name"] = "Aguada de tinta"
L["huntgood.hunts.trackerframe.mapscrap.description"] = "Una esquina arrancada de un mapa de caza: un sendero punteado, una brújula y el cerco del café de alguien."
L["huntgood.hunts.trackerframe.mapscrap.name"] = "Trozo de mapa"
L["huntgood.hunts.trackerframe.none.description"] = "Solo las líneas, sin nada dibujado alrededor."
L["huntgood.hunts.trackerframe.none.name"] = "Sin marco"
L["huntgood.hunts.trackerframe.slate.description"] = "Una pizarra en un marco atado con cuerda, escrita con tiza cada mañana y emborronada a mediodía."
L["huntgood.hunts.trackerframe.slate.name"] = "Pizarra de tiza"
L["huntgood.hunts.trackerframe.spyglass.description"] = "Esmalte azul marino entre dos rieles de latón, con el ocular de la esquina vuelto hacia la próxima caza."
L["huntgood.hunts.trackerframe.spyglass.name"] = "Borde de catalejo"
L["huntgood.hunts.trackerframe.wagerribbon.description"] = "Una cinta de seda morada con fleco dorado, para pescadores que no paran de ganarle a la casa en sus propias apuestas."
L["huntgood.hunts.trackerframe.wagerribbon.name"] = "Cinta del ganador"
L["huntgood.hunts.trackerframe.waxseal.description"] = "Pergamino con una línea roja en el margen y un sello de lacre en la esquina, como si la lista fuera oficial."
